const b = $input.first().json.body || $input.first().json;
// 2026-08-01 · el alta se acepta CON LO QUE VENGA. El único mínimo real es el NOMBRE
// del cliente: sin él no hay a quién describir ni qué descubrir.
//
// Caveat asumido (firmado): con poca señal el manual va a salir pobre o el juez no va a
// pasar. Está BIEN — el workflow ACEPTA y CORRE, y si no alcanza FALLA HONESTO
// (juez < 0.85 → cimiento.failed → Stop and Error). No se rechaza en la puerta ni se
// finge un manual bueno. El punto de fallo se MUEVE, no desaparece: un alta mínima
// llega más lejos y gasta más antes de fallar.
if (!b.client_name || !String(b.client_name).trim()) {
  throw new Error(
    'ONBOARDING_SIN_NOMBRE · el alta se acepta con lo mínimo, pero el nombre del ' +
    'cliente es imprescindible (no hay a quién describir ni qué descubrir).'
  );
}
// Defaults NO VACÍOS a propósito · el productor (ssLtw · Validate Deal Data) exige
// `industry` con truthiness y LANZA si viene vacío: con null el rechazo no
// desaparecería, se mudaría al sub-proceso (más adentro y más caro).
// Centinela 'unknown' (M3 red-team): valor único, en inglés como el resto de las claves,
// legible por máquina y distinguible de un dato real.
const _defaults_aplicados = [];
if (!b.industry)       { b.industry = 'unknown';       _defaults_aplicados.push('industry'); }
if (!b.contract_scope) { b.contract_scope = 'unknown'; _defaults_aplicados.push('contract_scope'); }
// FIX UBICACION (2026-08-08) · la geografia es parte del ESQUEMA del alta, no un extra.
// El alta de "Zero Risk Seguridad Industrial" (exec 85860) mando city=Guayaquil y country=EC ·
// los dos llegaron hasta ACA y la plantilla de la tarea NO los usaba: le ordenaba al
// descubridor INFERIR ciudad y pais del nombre y del sitio. Sin sitio, y con un nombre que
// colisiona con zerorisk.mx, infirio MEXICO, investigo otra empresa y devolvio {}.
// Costo del defecto: $1.23 y 21 min, sin manual, 0 ICP, 0 competidores.
// Acepta `location` libre, o `city`+`country`, o cualquiera suelto. NUNCA rechaza el alta
// (canon Pieza B · se acepta CON LO QUE VENGA): si falta, lo DECLARA en vez de hacer adivinar.
const _t = (v) => String(v == null ? '' : v).trim();
const _ciudad = _t(b.city || b.ciudad);
const _pais = _t(b.country || b.pais);
const _libre = _t(b.location || b.ubicacion);
b.city = _ciudad || null;
b.country = _pais || null;
b.location = _libre || [_ciudad, _pais].filter(Boolean).join(', ') || null;
b._sin_ubicacion = !b.location;
if (b._sin_ubicacion) _defaults_aplicados.push('location');
b._defaults_aplicados = _defaults_aplicados;
// LOTE-C Fix Â· pre-generate client UUID so downstream agent invocations
// share the same UUID as the persist upsert.
if (!b.client_id) {
  b.client_id = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}
// Gap 1 Â· brand assets passed through unchanged so Persist + Cascade pick them up.
b.website = b.website || b.domain || null;
b.client_logo_url = b.client_logo_url || null;
b.client_brand_colors = Array.isArray(b.client_brand_colors) ? b.client_brand_colors : null;
b.client_brand_fonts = Array.isArray(b.client_brand_fonts) ? b.client_brand_fonts : null;
return [{ json: b }];

