parameters.jsCode:
// Aggregate Service responses · AUGMENTED 2026-06-27 (dispatch multi-source) ·
// Tarea 3 · graceful degradation + discovery_package.sources[].
//
// 2026-09-06 (CC#1) · EL QUE ESCUCHA DEJA DE ESTAR SORDO.
// Medido en la corrida real 120994: la única llamada volvió con
// `validation_error: true` y acá se contó `successes: 1 · errors: 0`.
// Causa: se decidía con `r.success === false || !!r.error` y el Servicio
// devuelve `ok` · `rechazado` · `validation_error` · `errors[]` · `motivo`.
// Se leen AHORA los campos que el Servicio devuelve DE VERDAD, sin sacar los
// viejos (otros llamadores pueden seguir mandando `success`/`error`).
//
// Y aparecen dos casos que antes se contaban como éxito sin serlo:
//   · DESVIADO · objetivo sin actor (la web propia del cliente) · no fue al
//     Servicio · llega por la rama del Merge. No es éxito ni error: es «no le
//     tocaba a esta puerta».
//   · VACÍO · el ítem de guardia que emite un nodo sin datos. No es una llamada.
//
// Un actor caído se marca 'failed' y la corrida SIGUE · una fuente caída NUNCA
// aborta el descubrimiento entero.

const items = $input.all();
const summary = { total_calls: items.length, successes: 0, errors: 0, skipped_gate: 0, desviados: 0, vacios: 0, by_function: {} };
const sources = [];
let okCount = 0, failedCount = 0, totalResults = 0;

for (const it of items) {
  const crudo = it.json || {};
  // la respuesta del Servicio puede venir plana o dentro de `body` · lo de arriba manda
  const r = (crudo.body && typeof crudo.body === 'object' && !Array.isArray(crudo.body))
    ? Object.assign({}, crudo.body, crudo)
    : crudo;

  // ── ítem de guardia · no es una llamada, no se cuenta como nada ──
  if (!r || Object.keys(r).length === 0) { summary.vacios++; continue; }

  const fn = r.apify_function || 'unknown';
  summary.by_function[fn] = (summary.by_function[fn] || 0) + 1;

  // ── DESVIADO · vino por la rama del desvío · nunca tocó el Servicio ──
  const desviado = r._desviado === true ||
    (r.apify_function === null && !('ok' in r) && !('success' in r) && !('rechazado' in r));
  if (desviado) {
    summary.desviados++;
    sources.push({
      apify_function: null,
      status: 'desviado',
      count: 0,
      trust_level: r.trust_level || 'untrusted',
      source: r.source || 'onboarding_discovery',
      target_kind: r.target_kind || null,
      target_label: r.target_label || null,
      motivo: 'sin actor de Apify · no va a esa puerta',
    });
    continue;
  }

  if (r.status === 'skipped' || r.skip_reason) {
    summary.skipped_gate++;
    continue; // gate skip-markers are not a source success/failure
  }

  // ── EL RECHAZO ES UN ERROR · se leen los campos REALES del Servicio ──
  const rechazado =
    r.ok === false ||
    r.rechazado === true ||
    r.validation_error === true ||
    (Array.isArray(r.errors) && r.errors.length > 0);
  const failed = rechazado || r.success === false || !!r.error;

  const count =
    typeof r.result_count === 'number' ? r.result_count
    : Array.isArray(r.results) ? r.results.length
    : typeof r.count === 'number' ? r.count : 0;

  if (failed) {
    summary.errors++;
    failedCount++;
    sources.push({
      apify_function: fn, status: 'failed', count: 0,
      trust_level: r.trust_level || 'untrusted',
      source: r.source || 'apify_scrape',
      error:
        (Array.isArray(r.errors) && r.errors.length ? r.errors.join(' · ') : null) ||
        r.motivo ||
        (r.error && (r.error.message || String(r.error))) ||
        'actor failed',
    });
  } else {
    summary.successes++;
    okCount++;
    totalResults += count;
    sources.push({
      apify_function: fn, status: 'ok', count: count,
      trust_level: r.trust_level || 'untrusted',
      source: r.source || 'apify_scrape',
    });
  }
}

return [{ json: {
