// Model B · DISPATCH-ÚNICO guard · RE-ARMADO por E57 (CC#2 · 2026-09-16)
// 🔴 CON LLAVE desde E67 (CC#1 · 2026-09-16 · certificación E61 + E65).
//
// QUÉ CAMBIÓ EN E67 Y POR QUÉ: la marca `trigger_source` que exigía E57 es
// RASTRO, no llave · cualquiera que la conociera arrancaba un alta pagada
// (~US$ 2,5–3) sin pasar por la sala. Y el propio mensaje de rechazo enseñaba
// la marca. Ahora:
//   1. se exige una LLAVE REAL en la cabecera `x-sala-dispatch-key`, igual a
//      `SALA_DISPATCH_KEY` del entorno del motor (la pone Emilio · Railway ·
//      servicio n8n · MISMO valor que en Vercel, donde la lee el despachador);
//   2. si el motor NO tiene la llave, la puerta queda CERRADA (fail-closed);
//   3. la marca `trigger_source` se sigue exigiendo como rastro de quién despachó;
//   4. el rechazo dice QUÉ falta (para diagnóstico, adentro) · NO dice qué hay
//      que mandar. Hacia afuera el motor responde 500 sin detalle (el webhook
//      contesta desde el nodo «Respuesta · aceptado», que sólo corre si este
//      guarda pasó).
//
// El alta es OBRERO PURO: sólo corre si la SALA la despachó. Para arrancarla a
// mano: un sobre en la puerta de la sala (`POST /api/sala/intake`). Ése es el
// camino, y deja rastro.
const raw = $input.first().json;
const body = raw.body || raw;
const headers = raw.headers || {};

// ── 1 · la llave del motor · sin ella, cerrado ──
const llaveEsperada = String($env.SALA_DISPATCH_KEY || '').trim();
if (!llaveEsperada) {
  throw new Error(
    'ALTA_CERRADA · el motor no tiene la llave de despacho en su entorno' +
    ' (SALA_DISPATCH_KEY) · la puerta queda cerrada hasta que exista · E67.'
  );
}

// ── 2 · la llave que trae el pedido · comparación de largo constante ──
const llaveRecibida = String(headers['x-sala-dispatch-key'] || '');
let iguales = llaveRecibida.length === llaveEsperada.length;
for (let i = 0; i < llaveEsperada.length; i++) {
  iguales = (llaveRecibida.charCodeAt(i) === llaveEsperada.charCodeAt(i)) && iguales;
}
if (!iguales) {
  // adentro: qué faltó · afuera: nada (500 sin cuerpo útil)
  throw new Error(
    'ALTA_SIN_DESPACHO_DE_LA_SALA · llave de despacho ausente o incorrecta' +
    ' · esta corrida no la despachó la sala · E67.'
  );
}

// ── 3 · la marca de procedencia · rastro, no llave ──
const DESPACHADO_POR_LA_SALA = 'sala-router-dispatch';
if (body.trigger_source !== DESPACHADO_POR_LA_SALA) {
  throw new Error(
    'ALTA_SIN_DESPACHO_DE_LA_SALA · falta la marca de procedencia del despachador' +
    ' · esta corrida no la despachó la sala · E67.'
  );
}

// Los identificadores de correlación se siguen minteando si faltaran. NO son
// credenciales —son IDs de rastreo— y los consumen 12 nodos vivos del camino.
// Con un despacho de la sala vienen siempre; esto es red, no puerta.
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = Math.random() * 16 | 0;
  const v = c === 'x' ? r : (r & 0x3 | 0x8);
  return v.toString(16);
});
const _ids_minted = [];
if (!body._sala_correlation_id) { body._sala_correlation_id = uuid(); _ids_minted.push('_sala_correlation_id'); }
if (!body._journey_id)          { body._journey_id          = uuid(); _ids_minted.push('_journey_id'); }

return [{ json: { ...body, _modelb_guard: _ids_minted.length ? 'passed_minted' : 'passed', _ids_minted, _llave_verificada: true } }];

// E101 (CC#3 2026-09-18) · una nota que no decide nada no puede matar la corrida.
// Este nodo cuelga de la SALIDA DE ERROR de «[MODELB] Phase-boundary Emit · reconciliación OBSERVE» (tras 2 intentos y 25 s de tope): la nota se perdió,
// la corrida SIGUE con {ok:false, code:'nota_perdida'} hacia el mismo sucesor de siempre, y queda constancia:
// el mismo ítem viaja al avisador (5fkPLbZvQsQa1bcd) sin esperar · título «SE PERDIÓ UNA NOTA · la corrida SIGUE».
const base = String(($env && $env.N8N_BASE_URL) || 'https://n8n-production-72be.up.railway.app').replace(/\/+$/, '');
const nodo = "[MODELB] Phase-boundary Emit · reconciliación OBSERVE";
return $input.all().map((i) => {
  const e = (i.json && i.json.error) || {};
  const msg = String(typeof e === 'string' ? e : (e.message || e.description || (Object.keys(e).length ? JSON.stringify(e) : '') || 'sin mensaje')).slice(0, 400);
  const exId = String(($execution && $execution.id) || '?');
  const wfId = String(($workflow && $workflow.id) || '?');
  console.log('[nota-perdida] ' + nodo + ' · ' + msg + ' · la corrida SIGUE · corrida ' + exId);
  return { json: {
    ok: false, code: 'nota_perdida', nota_perdida: true, nodo, error: msg,
    execution: { id: exId, url: base + '/workflow/' + wfId + '/executions/' + exId, mode: ($execution && $execution.mode) || '?', lastNodeExecuted: nodo,
      error: { message: 'SE PERDIÓ UNA NOTA · la corrida SIGUE · ' + nodo + ' · ' + msg, node: { name: nodo } } },
    workflow: { id: wfId, name: ($workflow && $workflow.name) || '?' },
  } };
});

// Canon shape for Master Journey ugK3QrxkWq22Bly5 sub-workflow input.
// parse-validate-request (entry) reads $input.first().json.body.
// Required: journey (one of ACQUIRE|ONBOARD|PRODUCE|ALWAYS_ON|REVIEW)
//           client_id (string · except ACQUIRE)
//           trigger_type (string · 'manual' default)
//           params (object · free-form context)
// Fix root · Sprint 7 C5 cutover converted httpRequest→executeWorkflow
// but never wrapped payload as { body: {...} } per webhook entry shape.

const deal = $('Validate Deal Data').first().json;
const cascade = $input.first().json;

return [{
  json: {
    body: {
      journey: 'ONBOARD',
      client_id: deal.client_id,
      trigger_type: 'deal-won-onboarding',
      params: {
        client_name: deal.client_name || null,
        website: deal.website || null,
        industry: deal.industry || null,
        sala_correlation_id: deal._sala_correlation_id || null,
        journey_id: deal._journey_id || null,
        cascade_response: (cascade && typeof cascade === 'object') ? cascade : null,
        upstream_workflow_id: $workflow.id,
        upstream_execution_id: $execution.id,
      },
    },
  },
}];

// Canon · unwrap Vercel callback envelope (PR #185 contract) into the same shape
// the synchronous /api/agents/run-sdk used to return. Name preserved to keep
// existing references ($('Call Onboarding Specialist: Auto-Discovery').item.json.*)
// resolving transparently · zero text-edits across downstream consumer nodes.
//
// Vercel callback body shape · { status, agent_slug, client_id, result: <agentResult> }
// where agentResult mirrors sync-mode response body { response, result, discovery_output, ... }.
// If callback already arrives unwrapped (no `result` envelope) · pass through.

const cb = $input.first().json;
const unwrapped = (cb && typeof cb === 'object' && 'result' in cb) ? cb.result : cb;
return [{ json: unwrapped }];

// Synthesis Staging · Fase 3 · spec 5-fases CC#4 2026-06-09
// Consolida en memoria: agent output + Apify results → staging_package
// NO hace INSERT/UPDATE a ninguna tabla.

const discoveryItem = $('Confirm barato · competitor list').first().json;
const apifyAggregate = $('[APIFY-WIRE] Aggregate Service responses (onboarding_e2e)').first().json;
const dealData = $('Validate Deal Data').first().json;

const discoveryPkg = discoveryItem.discovery_package || {};
const apifyResults = apifyAggregate.results || apifyAggregate.apify_results || [];

// brand_book_draft: conclusiones del agente + evidencia Apify
const brandBookDraft = {
  competitive_landscape: discoveryPkg.discovery_summary || "",
  competitors: discoveryPkg.competitors || [],
  icp_signals: discoveryPkg.icp_signals || [],
  own_handles: discoveryPkg.own_handles || {},
  apify_evidence_count: apifyResults.length,
  draft_status: "pre_gate",
  source_agent: "onboarding-specialist",
  source_apify: "discovery_e2e_scrapes",
  generated_at: new Date().toISOString()
};

// icp_draft: señales ICP identificadas
const icpSignals = discoveryPkg.icp_signals || [];
const icpDraft = {
  segments: icpSignals,
  primary_segment: icpSignals[0] || null,
  segment_count: icpSignals.length,
  draft_status: "pre_gate"
};

// competitive_analysis_draft
const competitiveAnalysisDraft = {
