// Arma la carga de la segunda fase del alta · CC#3 2026-08-28.
// Los 11 datos nacen en DOS nodos distintos: por eso este nodo existe.
// Medido en raw/findings/2026-08-28-CC3-PARADA-paso-2-...md
const v = $('Validate Deal Data').item.json;
const d = $('Call Onboarding Specialist: Auto-Discovery').item.json || {};
return [{ json: {
  client_id: v.client_id,
  client_name: v.client_name,
  industry: v.industry,
  contract_scope: v.contract_scope,
  _journey_id: v._journey_id,
  _sala_correlation_id: v._sala_correlation_id,
  // los cuatro que NO llegan hoy · respaldo explicito para no reventar
  tenant_id: v.tenant_id || v.client_id,
  primary_contact_id: v.primary_contact_id || '',
  contact_email: v.contact_email || '',
  contact_name: v.contact_name || '',
  // nace en el descubridor, mucho despues que el validador
  discovery_result: d.discovery_output || d.response || null,
  // E93 (CC#1 2026-09-17) · quien lee el descubrimiento sabe qué le llegó: el punto de consulta
  // declara si el texto guardado está entero (response_complete) · si discovery_result cayó al
  // texto y ese texto está recortado, la carga lo dice · NUNCA un texto recortado como entero.
  discovery_response_complete: (typeof d.response_complete === 'boolean') ? d.response_complete : null,
  discovery_response_length_real: (typeof d.response_length_real === 'number') ? d.response_length_real : null,
  discovery_response_length_stored: (typeof d.response_length_stored === 'number') ? d.response_length_stored : null,
  discovery_result_note: (!d.discovery_output && d.response && d.response_complete !== true)
    ? ('DISCOVERY_RESULT ES TEXTO ' + (d.response_complete === false ? 'RECORTADO' : 'DE LARGO DESCONOCIDO') + ' · ' + String(d.response_note || '') + ' · no leerlo como entero')
    : (d.response_note || null),
} }];

// Track P · de qué intento estamos hablando AHORA.
// Lectura defensiva: antes del primer reintento el nodo de preparación no corrió
// y $() lanza. Eso NO es un fallo: es el caso normal del primer sondeo.
const base = 'rediscovery-' + $execution.id;
let rd_attempt = 0;
let rd_workflow_id = base;
try {
  const p = $('[RD] Preparar reintento').first().json;
  if (p && Number.isInteger(p.rd_attempt) && typeof p.rd_workflow_id === 'string' && p.rd_workflow_id) {
    rd_attempt = p.rd_attempt;
    rd_workflow_id = p.rd_workflow_id;
  }
} catch (e) { /* todavía no hubo ningún reintento · intento 0 */ }
return [{ json: { ...($input.first()?.json ?? {}), rd_attempt, rd_workflow_id } }];

// Track P · un reintento que se puede contar y que no reusa nada.
const base = 'rediscovery-' + $execution.id;
const previo = $('[RD] Sello de intento').first().json ?? {};
const intento = (Number.isInteger(previo.rd_attempt) ? previo.rd_attempt : 0) + 1;

// Dirección de retorno NUEVA · JAMÁS la ya consumida.
// Medido 2026-08-29 · los 53 retornos de `rediscovery-*` de toda la historia
// respondieron 409 (dirección consumida). Marcarla con el intento hace que un
// 409 futuro se pueda atribuir al intento que lo trajo, en vez de ser anónimo.
const cruda = String($execution.resumeUrl ?? '');
const rd_callback_url = cruda ? cruda + (cruda.includes('?') ? '&' : '?') + 'rd_attempt=' + intento : '';

return [{ json: {
  rd_attempt: intento,
  rd_workflow_id: base + '-r' + intento,
  rd_callback_url,
  rd_motivo: 'dispatch_status=error',
  rd_declarado_en: new Date().toISOString(),
} }];

// Track P · se acabó el cupo. Se PARA y se DECLARA · nunca se sigue preguntando.
const s = $('[RD] Sello de intento').first().json ?? {};
throw new Error(
  'RD_REINTENTOS_AGOTADOS · el re-descubrimiento murió en el medio y el tope de ' +
  2 + ' reintentos quedó agotado (intentos consumidos: ' + (s.rd_attempt ?? 0) + ') · ' +
  'ultima clave: ' + (s.rd_workflow_id ?? '(sin clave)') + ' · exec ' + $execution.id +
  ' · client ' + ($('Validate Deal Data').item.json.client_id || '(sin cliente)')
);

