// E29 · el texto del sitio, o el hueco. Tres estados, nunca un supuesto.
//
// REGLA 0 de la referencia del producto: un dato que falta se DECLARA y NUNCA
// detiene la salida. Acá eso significa que este nodo SIEMPRE emite un item.
//
// 'trajo'         → el Servicio leyó el sitio y hay texto
// 'sin_dato'      → se miró de verdad y no hay nada publicado (o fue ensayo)
// 'sin_respuesta' → no se pudo preguntar / el Servicio no contestó
// La diferencia importa: «no hay» NO es lo mismo que «no contestó».
const TOPE = 60000; // el endpoint del empleado corta en 120.000 · esto deja sitio de sobra

const r = (($input.first() || {}).json) || {};

// Un volcado JSON NO es texto de sitio. Si llega eso, es basura con forma de dato
// y no se cuela: el Servicio manda secciones de texto, una por página.
const pareceJsonCrudo = (s) => {
  const t = String(s || '').trim();
  if (!(t.startsWith('{') || t.startsWith('['))) return false;
  try { JSON.parse(t); return true; } catch (e) { return false; }
};

let estado = 'sin_respuesta';
let motivo = 'el Servicio no contestó · NO se preguntó de verdad · no es que no haya sitio';
let texto = '';
let paginas = 0;

if (r && r.ok === true) {
  const datos = String(r.datos || '');
  if (r.sin_resultados === true || datos.trim() === '') {
    estado = 'sin_dato';
    motivo = (r.cero && r.cero.motivo) ? String(r.cero.motivo) : 'se miró y el sitio no devolvió contenido';
  } else if (pareceJsonCrudo(datos)) {
    estado = 'sin_dato';
    motivo = 'lo que volvió era un volcado JSON, no el texto de las páginas · se descarta';
  } else {
    estado = 'trajo';
    motivo = '';
    texto = datos.length > TOPE ? datos.slice(0, TOPE) + '\n\n[…recortado en ' + TOPE + ' caracteres]' : datos;
    paginas = Number(r.chunks_count) || 0;
  }
} else if (r && r.ok === false) {
  estado = 'sin_respuesta';
  motivo = String(r.error || r.motivo || 'el Servicio contestó que no pudo');
}

// El ensayo NUNCA es 'trajo' · canon medido en producción el 10-sep: en ensayo el
// Servicio devuelve datos SINTÉTICOS. Un ensayo es un hueco, siempre.
if (r && r.dry_run === true && estado === 'trajo') {
  estado = 'sin_dato';
  motivo = 'FUE UN ENSAYO · el Servicio devolvió datos sintéticos, no medidos · no se miró de verdad';
  texto = '';
  paginas = 0;
}

return [{
  json: {
    sitio_estado: estado,
    sitio_motivo: motivo,
    sitio_texto: texto,
    sitio_paginas: paginas,
    sitio_caracteres: texto.length,
    sitio_guardado_en: (r && r.guardado_en) || null,
    sitio_es_materia_prima: (r && r.materia_prima) === true,
  },
  pairedItem: { item: 0 },
}];

// E71 · GUARDA · la puerta de la sala contesta 200 hasta cuando RECHAZA (canon §150 G4).
// Sin este nodo, un pedido de planeación rechazado (sin regla, sin credencial, sobre mal
// armado) se veria EXACTAMENTE igual que uno aceptado: 200 y silencio. Misma lección que
// el primer llamador (E57 · IXF3). Aca la corrida del alta termina en ERROR VISIBLE, sin
// deshacer nada: el alta ya termino; lo que fallo es pedir el paso siguiente.
const r = $input.first().json;
const cuerpo = r.body || r;
if (cuerpo.ok !== true) {
  throw new Error('PEDIDO_DE_PLANEACION_RECHAZADO · la puerta de la sala no acepto el sobre · code=' + (cuerpo.code || '?') + ' · ' + (cuerpo.detail || 'sin detalle'));
}
// `duplicate` NO es un error: el mismo recorrido pidiendo dos veces es un solo pedido.
return [{ json: { pedido_dejado_en_la_puerta: true, kind: cuerpo.kind, event_id: cuerpo.event_id || null, stream_id: cuerpo.stream_id || null, journey_type: cuerpo.journey_type || null, worker_workflow_id: cuerpo.worker_workflow_id || null } }];

// E87 · CC#1 · 2026-09-17 · el veredicto de competidores (veredicto) se PERDIÓ: no es «observar», es «no sé».
// Antes el flujo lo leía como «observar» y pagaba un re-descubrimiento que sobraba (E83 · US$ 0,59).
// Se PARA ruidoso (el avisador lo lleva a #alertas con esta causa). La respuesta ya pagada suele estar
// entera en agent_invocations (output_summary) · recuperarla es el arreglo A (E86), pendiente.
const v = $input.first().json || {};
throw new Error('VEREDICTO_PERDIDO · veredicto · no se · ' + String((v.razones || [])[0] || v._perdida || 'sin motivo').slice(0, 200)
  + ' · cliente ' + String(v.client_id || '(sin cliente)').slice(0, 8) + ' · corrida ' + $execution.id
  + ' · la respuesta pagada puede estar en agent_invocations.output_summary (workflow_execution_id=' + $execution.id + ') · NO se inventa un veredicto.');

// E87 · CC#1 · 2026-09-17 · el veredicto de competidores (re-gate) se PERDIÓ: no es «observar», es «no sé».
// Antes el flujo lo leía como «observar» y pagaba un re-descubrimiento que sobraba (E83 · US$ 0,59).
// Se PARA ruidoso (el avisador lo lleva a #alertas con esta causa). La respuesta ya pagada suele estar
// entera en agent_invocations (output_summary) · recuperarla es el arreglo A (E86), pendiente.
const v = $input.first().json || {};
throw new Error('VEREDICTO_PERDIDO · re-gate · no se · ' + String((v.razones || [])[0] || v._perdida || 'sin motivo').slice(0, 200)
  + ' · cliente ' + String(v.client_id || '(sin cliente)').slice(0, 8) + ' · corrida ' + $execution.id
  + ' · la respuesta pagada puede estar en agent_invocations.output_summary (workflow_execution_id=' + $execution.id + ') · NO se inventa un veredicto.');

// E99 (CC#3 2026-09-18) · arma la CAUSA con la que muere el alta cuando el cimiento no promueve.
// Siempre devuelve una cadena: el aviso a #alertas la lleva tal cual. NO decide nada · NO llama a nadie.
const j = (v) => { try { return JSON.stringify(v).slice(0, 400); } catch (e) { return String(v); } };
const inp = ($input.first() && $input.first().json) || {};
let ret = null, retErr = null;
try { ret = $('[JEFATURA] Execute Cimiento Track').first().json; } catch (e) { retErr = String(e && e.message || e); }

let causa;
if (inp.error !== undefined && inp.discovery_package !== undefined) {
  // salida de error del Execute Workflow: el cimiento MURIÓ · el ítem trae el error y el paquete
  const err = (inp.error && typeof inp.error === 'object') ? (inp.error.message || j(inp.error)) : String(inp.error);
  causa = 'CIMIENTO MURIÓ · ' + String(err).slice(0, 700) + ' · el manual NO se escribió · la causa entera está en la corrida del cimiento (ssLtwYPt7zxuvnM2 · el motor la borra en ~4 h)';
} else if (!ret || ret._cimiento_return !== true) {
  // E98: el cimiento devolvió un ítem que NO es su contrato (p. ej. el acuse del PDF) · no se sabe si promovió
  causa = 'EL CIMIENTO NO DEVOLVIÓ SU CONTRATO · llegó ' + (ret ? j(ret) : '(nada' + (retErr ? ' · ' + retErr : '') + ')') + ' · NO se sabe si el manual se promovió: mirar client_brand_books del cliente y la corrida del cimiento · nada se despacha (E99)';
} else {
  causa = 'CIMIENTO NO PROMOVIDO · track_pass=' + String(ret.track_pass) + ' · track_published=' + String(ret.track_published) + ' · motivo=' + String(ret.track_reason || '?') + ' · ciclos_agotados=' + String(ret.track_exhausted) + ' · fuente=' + String(ret._return_source || '?') + ' · el manual NO se escribió · retención para revisión humana (nada se despacha).';
}
if (typeof causa !== 'string' || !causa) causa = 'CIMIENTO NO PROMOVIDO · sin causa legible (E99)';
return [{ json: Object.assign({}, inp, { causa, _cimiento_ret: ret }) }];
